@startuml
class OOBank {}
class Branch {
  +address : string
  +branchNumber : int
}
class Division {
  +name : string
}
class Subdivision {
  +name : string
}
class Employee {
  +name : string
}
class Client {
  +name : string
}
class Account {
  +accountNumber : string
  +balance : float
  +creditOrOverdraftLimit : float
  +interestRate : float
  +monthlyFee : float
  +privileges : string[]
}
class MortgageAccount extends Account {}
class CheckingAccount extends Account {}
class CreditCardAccount extends Account {}
class SecondaryCard {
  +expiryDate : date
}

OOBank "1" *-- "*" Division : divided into
OOBank "1" *-- "*" Subdivision : divided into
Division "1" *-- "*" Subdivision : has
Division "1" -- "1" Employee : manager
Division "1" -- "*" Employee : has
Subdivision "1" -- "*" Branch : has
Branch "1" -- "*" Account : offers
Client "1..*" -- "1..*" Account : opens
Client "1" -- "0..1" Employee : personal banker
MortgageAccount "0..*" -- "1" Property : collateral
CreditCardAccount "1" *-- "*" SecondaryCard : has
@enduml

